DELETE FROM {target_table_name} AS f
WHERE ROWID IN (
    SELECT t.ROWID
    FROM {target_table_name} AS t
    INNER JOIN (SELECT * FROM {patch_table_name}) AS p
        ON {and_subquery_t}
);

